document.addEventListener('click',ev=>{if(!runtimeReady)return;const a=ev.target.closest('a[href]');if(!a||ev.defaultPrevented||ev.button!==0||ev.metaKey||ev.ctrlKey||ev.shiftKey||ev.altKey||a.hasAttribute('download')||a.target==='_blank')return;const raw=a.getAttribute('href');if(!raw||raw.startsWith('#')||/^(mailto:|tel:)/i.test(raw))return;const u=new URL(raw,document.baseURI);if(u.origin!==location.origin||!u.pathname.startsWith(baseURL.pathname))return;const p=parsePage(u.pathname,baseURL.pathname);if(p.type==='notfound')return;if(u.pathname===location.pathname&&u.hash){ev.preventDefault();history.pushState(null,'',u);document.getElementById(decodeURIComponent(u.hash.slice(1)))?.scrollIntoView({block:'start'});return;}ev.preventDefault();navigate(u);});
main.addEventListener('submit',async ev=>{const blogForm=ev.target.closest('[data-blog-search]');if(blogForm){ev.preventDefault();await loadRuntime();const q=blogForm.querySelector('input').value.toLowerCase().trim(),list=blogIndex.filter(p=>(page.type!=='blogCategory'||p.category===page.id)&&(!q||q.split(/\s+/).every(word=>(p.title+' '+p.summary+' '+p.category).toLowerCase().includes(word))));main.querySelector('[data-guide-grid]').innerHTML=list.length?list.map(blogCard).join(''):'<p>No guides matched. Try a shorter phrase.</p>';main.querySelector('[data-guide-count]').textContent=list.length+' guides';return;}const f=ev.target.closest('[data-tool-search]');if(!f)return;ev.preventDefault();liveSearch(f.querySelector('[name=q]'),false,true);});
