 recentTools();if(page.type==='tool'){const t=tools.find(t=>t.id===page.id);if(t){activation++;const ids=read('nepocore-recent',[]);save('nepocore-recent',[t.id,...(Array.isArray(ids)?ids:[]).filter(id=>id!==t.id)].slice(0,6));activateTool(t,main.querySelector('#tool-input'),main.querySelector('#tool-result'),activation);}}
